import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        Scanner sc = new Scanner(System.in);
        PrintWriter pw = new PrintWriter(System.out);
        int n = sc.nextInt();
        int k = sc.nextInt();
        int[] v = new int[10];
        for (int i = 0; i < k; i++) {
            v[sc.nextInt()] = 1;
        }
        int[] answer = {1};
        int p = n / 2;
        while (p > 0) {
            if ((p & 1) == 1) {
                answer = multiplyMod(answer, v, 998244353);
            }
            v = multiplyMod(v, v, 998244353);
            p >>= 1;
        }
        long total = 0;
        for (int x : answer) {
            total = (total + (long) x * x) % 998244353;
        }
        pw.println(total);
        pw.flush();
    }

    static int[] multiplyMod(int[] a, int[] b, int mod) {
        int need = a.length + b.length - 1;
        int size = Integer.highestOneBit(need - 1) << 1;
        double[] A = new double[size];
        double[] B = new double[size];
        for (int i = 0; i < a.length; i++) {
            int val = ((a[i] % mod) + mod) % mod;
            A[i] = val & ((1 << 15) - 1);
            A[i] += ((val >> 15) & 1) * 0.000001;
        }
        for (int i = 0; i < b.length; i++) {
            int val = ((b[i] % mod) + mod) % mod;
            B[i] = val & ((1 << 15) - 1);
            B[i] += ((val >> 15) & 1) * 0.000001;
        }
        fftTransform(A, false);
        fftTransform(B, false);
        double[] FbA = new double[size];
        double[] FbB = new double[size];
        for (int i = 0; i < size; i++) {
            int j = (size - i) & (size - 1);
            double aReal = (A[i] + A[j]) * 0.5;
            double aImag = (A[i] - A[j]) * 0.5;
            double bReal = (B[i] + B[j]) * 0.5;
            double bImag = (B[i] - B[j]) * 0.5;
            FbA[i] = aReal * bReal - aImag * bImag;
            FbB[i] = aReal * bImag + aImag * bReal;
        }
        fftTransform(FbA, true);
        fftTransform(FbB, true);
        int[] result = new int[need];
        for (int i = 0; i < need; i++) {
            long aa = Math.round(FbA[i]);
            long bb = Math.round(FbB[i]);
            long val = (aa + ((bb % mod) << 15)) % mod;
            result[i] = (int) val;
        }
        return result;
    }

    static void fftTransform(double[] a, boolean invert) {
        int n = a.length;
        for (int i = 1, j = 0; i < n; i++) {
            int bit = n >> 1;
            for (; (j & bit) != 0; bit >>= 1)
                j &= ~bit;
            j |= bit;
            if (i < j) {
                double temp = a[i];
                a[i] = a[j];
                a[j] = temp;
            }
        }
        for (int len = 2; len <= n; len <<= 1) {
            double angle = 2 * Math.PI / len * (invert ? -1 : 1);
            double wlenCos = Math.cos(angle);
            double wlenSin = Math.sin(angle);
            for (int i = 0; i < n; i += len) {
                double wCos = 1, wSin = 0;
                for (int j = 0; j < len / 2; j++) {
                    double u = a[i + j];
                    double v = a[i + j + len / 2] * wCos + a[i + j + len / 2] * wSin;
                    a[i + j] = u + v;
                    a[i + j + len / 2] = u - v;
                    double nextWCos = wCos * wlenCos - wSin * wlenSin;
                    wSin = wSin * wlenCos + wCos * wlenSin;
                    wCos = nextWCos;
                }
            }
        }
        if (invert) {
            for (int i = 0; i < n; i++) {
                a[i] /= n;
            }
        }
    }
}
